import{_ as a,o as e,c as r,a3 as f}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/money-dog/41-养成优秀品格的7条准则.md","filePath":"books/money-dog/41-养成优秀品格的7条准则.md","lastUpdated":1781445373000}'),h={name:"books/money-dog/41-养成优秀品格的7条准则.md"};function _(o,p,t,s,n,d){return e(),r("div",null,[...p[0]||(p[0]=[f('<p>养成优秀品格的7条准则</p><p>1．友好亲和</p><p>2．勇于承担</p><p>3．善待他人</p><p>4．帮助给予</p><p>5．感恩之心</p><p>6．勤学不辍</p><p>7．值得信赖</p><p>友好亲和</p><p>●　我有一个强烈的愿望，希望其他人能够像我一样生活美好而幸福。</p><p>●　我不会伤害任何人。我克制自己，不介入任何争端。</p><p>●　我谦虚有礼，尊重他人。我并不是永远正确。</p><p>勇于承担</p><p>●　遇事我能自我抉择。我能自行判断对某种情况应该作何反应。</p><p>●　我不受不公平之事的影响，而是将注意力集中在我能做的事情、我知道的知识和我拥有的东西之上。</p><p>●　我把责任推托给别人的同时，也把相应的权利转交给了对方。</p><p>善待他人</p><p>●　我只称赞他人。如果确实无法称赞他人，那就最好什么都不说。</p><p>●　我尽量不批评他人。如果不得不批评，也要用非常礼貌和友善的方式。</p><p>●　我将注意力集中在他人的优点和闪光点上。</p><p>帮助给予</p><p>●　我祝愿自己遇到过的所有人都能一切顺利。</p><p>●　我送给某人礼物，因为我想表达自己对他的好感。</p><p>●　最美好的事情莫过于帮助他人。我总是在想自己能够帮助谁，没有什么比这更令人快乐。</p><p>感恩之心</p><p>●　我总是心怀感恩，哪怕是对看似寻常的事情。</p><p>●　即便遇到了困难，我还是会关注值得感激的事物。</p><p>●　我对身边的人都充满感激之情，并非常享受和他们共度的美好时光。</p><p>勤学不辍</p><p>●　如果我骄傲自满，那无异于说自己不必再学任何东西了。因此我应该保持谦恭好学的态度。</p><p>●　我不仅要阅读好的书籍、写成功日记和知识笔记，还要尽可能多地向他人学习。</p><p>●　我不拿自己和别人比较，而是尽我所能做到最好。</p><p>值得信赖</p><p>●　我能否成功总是取决于自身培养出的习惯。</p><p>●　如果我是一个非常自律的人，我就能比那些虽有天赋但却懒惰散漫的人获得更多的成功。</p><p>●　我总是很守时。我信守对他人作出的承诺。</p><p>Table of Contents</p><p><a href="./01-目录">目录</a></p><p><a href="./02-小狗钱钱1">小狗钱钱1</a></p><p><a href="./03-童话与理财">童话与理财</a></p><p><a href="./04-前言">前言</a></p><p><a href="./05-第一章-白色的拉布拉多犬">第一章　白色的拉布拉多犬</a></p><p><a href="./06-第二章-梦想储蓄罐和梦想相册">第二章　梦想储蓄罐和梦想相册</a></p><p><a href="./07-第三章-达瑞，一个很会挣钱的男孩">第三章　达瑞，一个很会挣钱的男孩</a></p><p><a href="./08-第四章-堂兄的挣钱之道">第四章　堂兄的挣钱之道</a></p><p><a href="./09-第五章-钱钱以前的主人">第五章　钱钱以前的主人</a></p><p><a href="./10-第六章-爸爸妈妈犯下的错误">第六章　爸爸妈妈犯下的错误</a></p><p><a href="./11-第七章-在金先生家">第七章　在金先生家</a></p><p><a href="./12-第八章-陶穆太太">第八章　陶穆太太</a></p><p><a href="./13-第九章-冒险经历">第九章　冒险经历</a></p><p><a href="./14-第十章-在地下室里">第十章　在地下室里</a></p><p><a href="./15-第十一章-爸爸妈妈不明白">第十一章　爸爸妈妈不明白</a></p><p><a href="./16-第十二章-陶穆太太归来">第十二章　陶穆太太归来</a></p><p><a href="./17-第十三章-巨大的危机">第十三章　巨大的危机</a></p><p><a href="./18-第十四章-投资俱乐部">第十四章　投资俱乐部</a></p><p><a href="./19-第十五章-演-讲">第十五章　演　讲</a></p><p><a href="./20-第十六章-俱乐部的投资行动">第十六章　俱乐部的投资行动</a></p><p><a href="./21-第十七章-爷爷奶奶害怕风险">第十七章　爷爷奶奶害怕风险</a></p><p><a href="./22-第十八章-大冒险的结局">第十八章　大冒险的结局</a></p><p><a href="./23-自力更生——写给成年人的后记">自力更生——写给成年人的后记</a></p><p><a href="./24-附-录">附　录</a></p><p><a href="./25-小狗钱钱2">小狗钱钱2</a></p><p><a href="./26-童话与理财">童话与理财</a></p><p><a href="./27-第一章-奖学金">第一章　奖学金</a></p><p><a href="./28-第二章-白色石头">第二章　白色石头</a></p><p><a href="./29-第三章-放大镜">第三章　放大镜</a></p><p><a href="./30-第四章-论文">第四章　论文</a></p><p><a href="./31-第五章-前往加利福尼亚">第五章　前往加利福尼亚</a></p><p><a href="./32-第六章-寄宿学校">第六章　寄宿学校</a></p><p><a href="./33-第七章-好老师">第七章　好老师</a></p><p><a href="./34-第八章-危险">第八章　危险</a></p><p><a href="./35-第九章-好老师的秘密">第九章　好老师的秘密</a></p><p><a href="./36-第十章-7条准则">第十章　7条准则</a></p><p><a href="./37-第十一章-演讲比赛">第十一章　演讲比赛</a></p><p><a href="./38-第十二章-事件">第十二章　事件</a></p><p><a href="./39-第十三章-回家">第十三章　回家</a></p><p><a href="./40-第十四章-道别">第十四章　道别</a></p><p><a href="./41-养成优秀品格的7条准则">养成优秀品格的7条准则</a></p>',78)])])}const i=a(h,[["render",_]]);export{m as __pageData,i as default};
